$_MODULE['<{supercheckout}prestashop>supercheckout_b280505cf0153d23bd198a55dd157465'] = "1. Moet kleine pictogrammen wijzigen naast // inlogopties, afleveradres, leveringsmethode, betaalmethode, uw bestelling bevestigen // Rechten vooraan?";
$_MODULE['<{supercheckout}prestashop>supercheckout_bed27d1f5777683800a9de0b5e5f0c1b'] = "Om die pictogrammen te wijzigen, vervangt u die IMAE's in de volgende map op uw server.";
$_MODULE['<{supercheckout}prestashop>supercheckout_e7f14d1cc6f006ed665a96bdc2bc824c'] = "2. Radioknoppen voor zowel de heer als Mrs. zijn altijd gecontroleerd?";
$_MODULE['<{supercheckout}prestashop>supercheckout_60dbf8e43fb6050332115ff49a63e4a9'] = "Als zowel MR- als MRS. -radioknoppen altijd worden aangevinkt, voeg dan de onderstaande code toe in aangepast CSS -veld van ons tabblad Module Customizer om het probleem op te lossen.";
$_MODULE['<{supercheckout}prestashop>supercheckout_22ee63f888f86d8628b9ae6ef3dd2db3'] = "3. Derde kolom is niet correct uitgelijnd of volledig probleem met de bureaublad?";
$_MODULE['<{supercheckout}prestashop>supercheckout_80129d0e4495deba9345b981ea9a3781'] = "Hoogstwaarschijnlijk is uw themasjabloon CSS in strijd met onze module. Fix voor dit probleem is heel eenvoudig. Voeg vriendelijk de volgende code toe in aangepast CSS -veld in het tabblad Customizer van onze module beheerdersinstelling.";
$_MODULE['<{supercheckout}prestashop>supercheckout_c074059f10a9694301d1286011a7d813'] = "In het geval dat uw probleem niet is opgelost, probeer dit percentage te wijzigen om aan uw thema te passen, anders neemt u contact met ons op met admin- en FTP -inloggegevens.";
$_MODULE['<{supercheckout}prestashop>supercheckout_97ac14c0d9218bee4eef636bd183ad6c'] = "4. Wilt u een extra veld in adresformulier toevoegen?";
$_MODULE['<{supercheckout}prestashop>supercheckout_dc72e0ed0f63106d79f8e597023ec780'] = "Standaard is het niet mogelijk om het aangepast veld in onze module toe te voegen, als u wilt dat we deze aangepaste wijziging voor u kunnen aanbrengen voor extra kosten. Neem contact met ons op met uw volledige vereisten.";
$_MODULE['<{supercheckout}prestashop>supercheckout_2d0bf4cd950c749b4d9b9148981c2c3b'] = "5. Module van derden werkt niet?";
$_MODULE['<{supercheckout}prestashop>supercheckout_99454524f58d75bc69142c51db698004'] = "Modules van derden worden alleen gemaakt voor de standaardafcheck van Prestashop. Ze kunnen al dan niet met onze module werken. Als ze niet met onze module werken, moeten enkele aangepaste wijzigingen worden aangebracht om ze compatibel te maken met onze module.";
$_MODULE['<{supercheckout}prestashop>supercheckout_89b45d262a3b8d997d082e81abca5a2d'] = "6. Wil je dat we een specifieke functie implementeren voor extra kosten?";
$_MODULE['<{supercheckout}prestashop>supercheckout_a074e8c20a65c62c9e5187271f4d5124'] = "Ja, u kunt contact met ons opnemen met volledige vereisten. Als wijzigingen mogelijk zijn, kunnen we ze voor extra kosten implementeren.";
$_MODULE['<{supercheckout}prestashop>supercheckout_55247fb7e9f42c8afc3186ea045737f8'] = "7. geconfronteerd met een van deze problemen?";
$_MODULE['<{supercheckout}prestashop>supercheckout_f702ec5deb9b0e80db05af6912900fea'] = "De reden voor deze fouten is niet specifiek. Als u met een van deze problemen wordt geconfronteerd, neem dan vriendelijk contact met ons op met uw admin- en FTP -details.";
$_MODULE['<{supercheckout}prestashop>supercheckout_e5d097e11c4399cc25ec536ac8d8c451'] = "8. Betalingsmethode geeft geen additinale kosten weer?";
$_MODULE['<{supercheckout}prestashop>supercheckout_fe6ce161b3b7839ad53e310b4229e7d2'] = "Het is een zeer zeldzame probleem en neem in het geval dat u ermee onder ogen komt, contact met ons op uw admin en FTP -inloggegevens zodat we dit probleem voor u kunnen oplossen.";
$_MODULE['<{supercheckout}prestashop>supercheckout_5ed215b5ee0001f041ae4c9a287a5517'] = "9. Vertaalde tekst reflecteert niet aan de voorkant?";
$_MODULE['<{supercheckout}prestashop>supercheckout_08ca6a947fc70d8babef7f7ec6aeb024'] = "Probeer het opnieuw na het wissen van uw Prestashop-cache met behulp van Advance Parameter-> Prestaties-> Cache-knop Wissen. Als uw probleem zelfs daarna aanhoudt, zorg er dan voor dat uw themadirectory niet ons module vertaalbestand bevat. Ga naar uw themadirectory om dit te controleren";
$_MODULE['<{supercheckout}prestashop>supercheckout_3c82d67a74d281ef174bf95b12c24a8a'] = "In deze modules directory zou er geen superCHECKOUT -directory moeten, voor het geval het bestaat, hernoem het gewoon naar iets anders.";
$_MODULE['<{supercheckout}prestashop>supercheckout_a6f90da86996e1221fda518644259beb'] = "Wanneer u tekst vertaalt uit ons module admin -paneel, slaan onze module vertaalde tekst op in";
$_MODULE['<{supercheckout}prestashop>supercheckout_d7529a65fb108570a2aed2400414c23d'] = "Maar wanneer er een vertaling bestaat in uw themamap, kiest onze module van daaruit tekst en reflecteert uw vertaalde tekst niet in de voorkant.";
$_MODULE['<{supercheckout}prestashop>supercheckout_bf4ad7ba59bbead463e5e2139692e642'] = "Nu rijst de vraag, in welk geval de themapirectory onze module vertaalde tekstbestand kan hebben.";
$_MODULE['<{supercheckout}prestashop>supercheckout_0787d403d8b13efef7fe01c7abe369d7'] = "Wanneer u de standaard vertaalfunctie van Prestashop gebruikt, slaat het vertaalde tekst op in themapirectory en onze module gebruikt tekst uit deze thema's directory in plaats van tekst te gebruiken vanuit de module -directory.";
$_MODULE['<{supercheckout}prestashop>supercheckout_2c82c4b35996db294c4abb8e159fe18b'] = "10. De afbeelding van de betalingsmethode komt niet?";
$_MODULE['<{supercheckout}prestashop>supercheckout_84eac6be4143de5987dcb220f16c5c11'] = "Onze module toont betaalmethoden afbeeldingen uit hun hoofdmap (modules/paying_method_name). Als een betaalmethode geen afbeelding in hun hoofdmap heeft, wordt er geen afbeelding weergegeven.";
$_MODULE['<{supercheckout}prestashop>supercheckout_ef4fc15d99eb596bf5b0238e0f4f59a0'] = "Om de afbeelding van die betaalmethode weer te geven, upload je de afbeelding vriendelijk naar de map van de betalingsmodule. Afbeeldingsnaam moet hetzelfde zijn als naam van de Directory van de betaalmethode. U kunt elk beeldformaat gebruiken, bijv. JPG, PNG etc.";
$_MODULE['<{supercheckout}prestashop>supercheckout_efb389635d8c846c7be280bf8e536f61'] = "Bijvoorbeeld: om de IPAY -betaalmodule -afbeelding weer te geven, moet u de afbeelding toevoegen";
$_MODULE['<{supercheckout}prestashop>supercheckout_30575781a136fd134c3b4147d28ab0a3'] = "Directory- en beeldnaam moeten Iupay zijn. Afbeeldingsuitbreiding kan alles zijn en de aanbevolen beeldresolutie is 95x20.";
