$_MODULE['<{supercheckout}prestashop>supercheckout_8bb93b7b833f2efec92d3bf7f40ca639'] = "11. Aan de voorkant wanneer u klikt op inloggen of de bestelknop plaatsen, gebeurt er niets?";
